window.CURRICULUM_2 = [{"id":"daybeach2","index":0,"name":"A Day at the Beach","subtitle":"Counting in groups","emoji":"🏖️","palette":{"from":"#fbbf24","to":"#92400e"},"lessons":[{"id":"db1","title":"Shells in Groups","icon":"🐚","kind":"lesson","story":"Lina and Rani are at the beach! They find lots of shells and want to count them fast.","teach":[{"title":"Count in groups","body":"Counting one by one is slow. Make groups of 10 and count 10, 20, 30!","visual":"🐚"},{"title":"Groups and loose ones","body":"2 groups of 10 and 3 loose ones make 23.","visual":"🎈"}],"questions":[{"kind":"numeric","prompt":"Lina made 3 necklaces. Each has 10 shells. How many shells in all? 🐚","answer":30,"explain":"Count in tens: 10, 20, 30."},{"kind":"numeric","prompt":"Count in tens: 10, 20, 30, 40, ___ ?","answer":50,"explain":"After 40 in tens comes 50."},{"kind":"mcq","prompt":"What is a quicker way to count many things?","options":["Count with eyes closed","Count in groups","Count one by one"],"answer":1,"explain":"Groups of 10 make counting quick and easy."},{"kind":"numeric","prompt":"A shop has 2 groups of 10 balloons and 3 loose balloons. How many balloons? 🎈","answer":23,"explain":"20 and 3 more make 23."}]},{"id":"db2","title":"Tasty Chikoos","icon":"🥭","kind":"lesson","story":"Manoj sells chikoos at the beach. He puts 10 chikoos in each tray.","teach":[{"title":"Trays of ten","body":"25 chikoos fill 2 trays of ten. 5 chikoos are left over.","visual":"🧺"},{"title":"Tens and ones","body":"52 is 5 tens and 2 ones. It is 50 + 2.","visual":"🔢"}],"questions":[{"kind":"numeric","prompt":"Manoj has 25 chikoos. How many full trays of ten can he fill?","answer":2,"explain":"25 is 2 tens and 5 ones."},{"kind":"numeric","prompt":"Manoj has 43 chikoos. How many chikoos are left after filling the trays of ten?","answer":3,"explain":"43 is 4 tens and 3 ones."},{"kind":"numeric","prompt":"6 tens and 9 ones make which number?","answer":69,"explain":"60 and 9 make 69."},{"kind":"mcq","prompt":"Which number is the same as 40 + 6?","options":["64","10","40","46"],"answer":3,"explain":"4 tens and 6 ones make 46."}]},{"id":"db3","title":"Make 100!","icon":"💯","kind":"lesson","story":"Rani and Lina play a block game. They want to build a big grid of 100!","teach":[{"title":"Ten strip","body":"1 ten strip has 10 units. Ten units swap for 1 ten strip.","visual":"🟨"},{"title":"Make 100","body":"10 ten strips make 100 units. 70 and 30 make 100 too!","visual":"💯"}],"questions":[{"kind":"numeric","prompt":"How many units are in 3 ten strips?","answer":30,"explain":"3 tens are 30."},{"kind":"numeric","prompt":"How many units are in 10 ten strips?","answer":100,"explain":"10 tens make 100."},{"kind":"numeric","prompt":"7 ten strips are yellow. The rest of the 10 are red. How many are red?","answer":3,"explain":"10 - 7 = 3 red ten strips."},{"kind":"numeric","prompt":"60 + ___ = 100. What number is missing?","answer":40,"explain":"60 and 40 make 100."}]},{"id":"db4","title":"More or Less","icon":"🍊","kind":"lesson","story":"Suraj and Lina arrange oranges in trays. Which tray has more oranges?","teach":[{"title":"Look at the tens first","body":"43 has 4 tens. 34 has only 3 tens. So 43 is more.","visual":"🍊"},{"title":"Same tens? Check ones","body":"43 and 47 both have 4 tens. 47 has more ones, so 47 is more.","visual":"⚖️"}],"questions":[{"kind":"mcq","prompt":"Which is more: 43 oranges or 34 oranges? 🍊","options":["They are the same","34 oranges","43 oranges"],"answer":2,"explain":"43 has 4 tens and 34 has only 3 tens."},{"kind":"mcq","prompt":"Which is more: 43 oranges or 47 oranges?","options":["47 oranges","They are the same","43 oranges"],"answer":0,"explain":"Both have 4 tens, but 47 has 7 ones."},{"kind":"mcq","prompt":"Which is less: 27 oranges or 72 oranges?","options":["72 oranges","They are the same","27 oranges"],"answer":2,"explain":"27 has 2 tens. 72 has 7 tens."},{"kind":"mcq","prompt":"Fill in: 56 shells are ___ than 65 shells.","options":["the same","more","less"],"answer":2,"explain":"56 has 5 tens. 65 has 6 tens."}]},{"id":"db5","title":"Biggest and Smallest","icon":"🔤","kind":"lesson","story":"Lina plays Who Am I? with number cards. Can you guess the secret numbers?","teach":[{"title":"Two-digit numbers","body":"The biggest two-digit number is 99. The smallest is 10.","visual":"🔟"},{"title":"Make the biggest","body":"Put the bigger card in the tens place. Cards 3 and 5 make 53.","visual":"🃏"}],"questions":[{"kind":"numeric","prompt":"I am the largest two-digit number. Who am I?","answer":99,"explain":"99 is the largest two-digit number."},{"kind":"numeric","prompt":"I am the smallest two-digit number. Who am I?","answer":10,"explain":"10 is the smallest two-digit number."},{"kind":"numeric","prompt":"Lina has cards 3 and 5. What is the largest number she can make?","answer":53,"explain":"Put 5 in the tens place to get 53."},{"kind":"numeric","prompt":"I am the largest two-digit number with 2 at the ones place. Who am I?","answer":92,"explain":"9 tens and 2 ones make 92."}]},{"id":"db6","title":"Boat Race Finish","icon":"🛶","kind":"lesson","story":"It is the snake boat race! Help Lina find who came first, second and third.","teach":[{"title":"Positions","body":"We say 1st, 2nd, 3rd, 4th and 5th for the order in a race.","visual":"🥇"}],"questions":[{"kind":"mcq","prompt":"Red came 1st, Blue came 2nd, Green came 3rd. Which boat came 3rd? 🛶","options":["Blue","Green","Red"],"answer":1,"explain":"The 3rd boat is Green."},{"kind":"numeric","prompt":"Blue boat came just after the Red boat. Red was 1st. What number position is Blue?","answer":2,"explain":"After 1st comes 2nd."},{"kind":"numeric","prompt":"4 boats finished before the Pink boat. What number position is Pink?","answer":5,"explain":"4 boats first, so Pink is 5th."},{"kind":"mcq","prompt":"Rani was 1st, Surbhi was 2nd, Manoj was 3rd. Who was last?","options":["Manoj","Rani","Surbhi"],"answer":0,"explain":"Manoj was 3rd, the last one."}]},{"id":"db-boss","title":"Beach Boss: Captain Crab","icon":"🦀","kind":"boss","boss":{"name":"Captain Crab","taunt":"Can you count faster than my claws?"},"story":"Captain Crab hides the treasure! Count in tens and tens-and-ones to win.","teach":[{"title":"Beach review","body":"Count in tens. Tens and ones make two-digit numbers. 10 tens make 100.","visual":"🏖️"}],"questions":[{"kind":"numeric","prompt":"4 necklaces have 10 shells each. How many shells in all? 🐚","answer":40,"explain":"Count in tens: 10, 20, 30, 40."},{"kind":"numeric","prompt":"Manoj fills 3 trays of ten and has 8 loose chikoos. How many in all?","answer":38,"explain":"30 and 8 make 38."},{"kind":"numeric","prompt":"7 tens and 3 ones make which number?","answer":73,"explain":"70 and 3 make 73."},{"kind":"numeric","prompt":"30 + ___ = 100. What number is missing?","answer":70,"explain":"30 and 70 make 100."},{"kind":"mcq","prompt":"Which is more: 68 shells or 86 shells?","options":["68 shells","They are the same","86 shells"],"answer":2,"explain":"86 has 8 tens. 68 has 6 tens."},{"kind":"numeric","prompt":"Cards 4 and 8. What is the largest two-digit number you can make?","answer":84,"explain":"Put the bigger card, 8, in the tens place."},{"kind":"mcq","prompt":"Green came 3rd. Orange came right after Green. Which position is Orange?","options":["5th","4th","3rd","2nd"],"answer":1,"explain":"After 3rd comes 4th."}]}]},{"id":"shapesaround2","index":1,"name":"Shapes Around Us","subtitle":"3D shapes","emoji":"🧊","palette":{"from":"#60a5fa","to":"#1e3a8a"},"lessons":[{"id":"sa1","title":"Shapes in Music","icon":"🥁","kind":"lesson","story":"Lina visits the mela music stall. Drums, matkas and harmoniums sit in a row!","teach":[{"title":"A drum is a cylinder","body":"A drum has two flat round faces. Its shape is called a cylinder.","visual":"🥁"},{"title":"A matka is round","body":"A matka is round like a ball. A ball's shape is called a sphere.","visual":"🏺"}],"questions":[{"kind":"mcq","prompt":"A drum 🥁 has two flat round faces. What shape is it?","options":["Cube","Cone","Sphere","Cylinder"],"answer":3,"explain":"A drum is shaped like a cylinder."},{"kind":"mcq","prompt":"A matka 🏺 is round like a ball ⚽. What shape is it like?","options":["Cuboid","Sphere","Cylinder","Cube"],"answer":1,"explain":"Round like a ball means a sphere."},{"kind":"mcq","prompt":"A shehnai gets wider and wider at one end. Which shape is it like?","options":["Cube","Cuboid","Sphere","Cone"],"answer":3,"explain":"A shape that is pointy at one end and wide at the other is a cone."},{"kind":"mcq","prompt":"A harmonium 🎹 is like a box with flat faces and corners. Which shape?","options":["Cylinder","Cuboid","Cone","Sphere"],"answer":1,"explain":"A box shape with 6 flat faces is a cuboid."}]},{"id":"sa2","title":"Cube and Cuboid","icon":"🎁","kind":"lesson","story":"Heena and Atif want to decorate a gift box for a friend. Let us help them!","teach":[{"title":"Faces, edges, corners","body":"Flat sides are faces. Faces meet at edges, and edges meet at corners.","visual":"📦"},{"title":"Cube and cuboid","body":"A cube and a cuboid both have 6 faces, 12 edges and 8 corners.","visual":"🎲"}],"questions":[{"kind":"numeric","prompt":"A gift box 🎁 is a cuboid. How many faces does it have?","answer":6,"explain":"A cuboid has 6 faces."},{"kind":"numeric","prompt":"How many edges does a cube 🎲 have?","answer":12,"explain":"A cube has 12 edges."},{"kind":"numeric","prompt":"How many corners does a cuboid 📦 have?","answer":8,"explain":"A cuboid has 8 corners."},{"kind":"mcq","prompt":"A dice 🎲 has 6 square faces that are all the same. What shape is it?","options":["Cube","Sphere","Cylinder","Cone"],"answer":0,"explain":"A dice is a cube."}]},{"id":"sa3","title":"Cylinder, Cone and Sphere","icon":"🍦","kind":"lesson","story":"Rani finds a ball, a tin and an ice-cream cone at the mela. What shapes are they?","teach":[{"title":"Cylinder and sphere","body":"A cylinder has 3 faces, 2 edges and no corners. A sphere has 1 face, no edges and no corners.","visual":"🥫"},{"title":"Cone","body":"A cone has 2 faces, 1 edge and 1 corner. A party hat is a cone.","visual":"🍦"}],"questions":[{"kind":"numeric","prompt":"How many faces does a cylinder 🥫 have?","answer":3,"explain":"A cylinder has 3 faces: 2 flat and 1 curved."},{"kind":"numeric","prompt":"How many corners does a cone 🍦 have?","answer":1,"explain":"A cone has 1 corner at its tip."},{"kind":"mcq","prompt":"Which shape has no edges and no corners?","options":["Cuboid","Cone","Sphere","Cube"],"answer":2,"explain":"A sphere is smooth all over."},{"kind":"numeric","prompt":"How many edges does a cone 🍦 have?","answer":1,"explain":"A cone has 1 edge around its flat round face."}]},{"id":"sa4","title":"Stars, Ribbons and Pompoms","icon":"🌟","kind":"lesson","story":"Atif has stars, ribbons and pompom balls. Let us decorate some shapes!","teach":[{"title":"Where things go","body":"Put 1 star on each face. Put 1 ribbon on each edge.","visual":"🌟"},{"title":"Pompom balls","body":"Put 1 pompom ball on each corner. A cube needs 6 stars, 12 ribbons and 8 pompoms.","visual":"🎀"}],"questions":[{"kind":"numeric","prompt":"How many stars 🌟 does a cube need, one on each face?","answer":6,"explain":"A cube has 6 faces, so it needs 6 stars."},{"kind":"numeric","prompt":"How many ribbons 🎀 does a cuboid need, one on each edge?","answer":12,"explain":"A cuboid has 12 edges, so it needs 12 ribbons."},{"kind":"numeric","prompt":"How many pompom balls does a cone need, one on each corner?","answer":1,"explain":"A cone has 1 corner, so it needs 1 pompom ball."},{"kind":"numeric","prompt":"A cylinder gets a star on each face and a ribbon on each edge. How many things in all?","answer":5,"explain":"3 stars and 2 ribbons make 3 + 2 = 5."}]},{"id":"sa5","title":"Touch and Tell","icon":"🙈","kind":"lesson","story":"Lina wears a blindfold and picks objects by touch. Help her guess the shapes!","teach":[{"title":"Rolling","body":"Round shapes like a sphere roll easily. Flat faces help shapes sit still.","visual":"⚽"},{"title":"Stacking","body":"Shapes with flat faces stack well. Boxes and cubes pile up high!","visual":"🧱"}],"questions":[{"kind":"mcq","prompt":"Lina's object has exactly one corner. What is it?","options":["Cube","Sphere","Cylinder","Cone"],"answer":3,"explain":"Only a cone has exactly one corner."},{"kind":"mcq","prompt":"Which one has no corners?","options":["Ball ⚽","Box 📦","Dice 🎲"],"answer":0,"explain":"A ball is a sphere, and a sphere has no corners."},{"kind":"mcq","prompt":"Which one rolls best?","options":["Ball ⚽","Box 📦","Dice 🎲"],"answer":0,"explain":"A ball is round, so it rolls."},{"kind":"mcq","prompt":"Which can you stack easily, one on top of another?","options":["Dice 🎲","Ball ⚽","Orange 🍊"],"answer":0,"explain":"Flat faces make shapes easy to stack."},{"kind":"numeric","prompt":"A cube has 8 corners and a cone has 1 corner. How many corners in all?","answer":9,"explain":"8 + 1 = 9 corners."}]},{"id":"sa-boss","title":"Shape Master","icon":"🏆","kind":"boss","boss":{"name":"Captain Cube","taunt":"Can you name every shape at the mela?"},"story":"Captain Cube blocks the gate of the mela. Show him you know all the shapes!","teach":[{"title":"Shapes review","body":"Cube and cuboid: 6 faces, 12 edges, 8 corners. Cylinder, cone and sphere are round shapes.","visual":"🧊"}],"questions":[{"kind":"mcq","prompt":"A drum 🥁 is shaped like which solid?","options":["Cylinder","Cube","Cone","Sphere"],"answer":0,"explain":"A drum is a cylinder."},{"kind":"numeric","prompt":"How many faces does a cuboid have?","answer":6,"explain":"A cuboid has 6 faces."},{"kind":"numeric","prompt":"How many edges does a cube have?","answer":12,"explain":"A cube has 12 edges."},{"kind":"numeric","prompt":"How many corners do a cone and a sphere have in all?","answer":1,"explain":"A cone has 1 corner and a sphere has 0, so 1 + 0 = 1."},{"kind":"mcq","prompt":"Which shape has 2 faces, 1 edge and 1 corner?","options":["Cone","Cube","Sphere","Cylinder"],"answer":0,"explain":"That is a cone."},{"kind":"mcq","prompt":"Which shape is smooth, has no corners and rolls?","options":["Cuboid","Sphere","Cone","Cube"],"answer":1,"explain":"A sphere is round all over."},{"kind":"numeric","prompt":"A cylinder gets a star on each face. How many stars?","answer":3,"explain":"A cylinder has 3 faces, so it needs 3 stars."}]}]},{"id":"funnumbers2","index":2,"name":"Fun with Numbers","subtitle":"Numbers up to 100","emoji":"🧮","palette":{"from":"#fb923c","to":"#7c2d12"},"lessons":[{"id":"fn1","title":"The Ginladi Bead Frame","icon":"🧮","kind":"lesson","story":"Lina found a magic ginladi in the mela! Count its beads to open the gate.","teach":[{"title":"Rows of ten","body":"A ginladi has rows of 10 beads. Count the full rows first.","visual":"🧮"},{"title":"Tens and ones","body":"4 tens and 4 ones make 44. Tens go first, then ones.","visual":"🔟"}],"questions":[{"kind":"numeric","prompt":"A ginladi has 3 full rows of 10 beads and 8 more beads. How many beads in all?","answer":38,"explain":"3 tens is 30, and 8 more makes 38."},{"kind":"mcq","prompt":"Which number is 6 tens and 5 ones?","options":["11","60","56","65"],"answer":3,"explain":"6 tens is 60, and 5 ones makes 65."},{"kind":"numeric","prompt":"98 is 9 tens and how many ones?","answer":8,"explain":"The last digit of 98 is 8, so there are 8 ones."},{"kind":"numeric","prompt":"How many beads? 🔴🔴🔴🔴🔴🔴🔴🔴🔴🔴 🔴🔴🔴🔴🔴🔴🔴🔴🔴🔴 🔴🔴🔴","answer":23,"explain":"2 full rows of ten is 20, and 3 more makes 23."}]},{"id":"fn2","title":"Hops on the Number Strip","icon":"🦋","kind":"lesson","story":"A butterfly and a frog race along the number strip. Help them find the flowers!","teach":[{"title":"Forward and backward","body":"Forward steps take you to a bigger number. Backward steps take you to a smaller number.","visual":"🐸"},{"title":"Many hops","body":"Do one hop at a time. Write the number you land on each time.","visual":"🦋"}],"questions":[{"kind":"numeric","prompt":"A frog sits on 12. It jumps 5 steps forward. Where does it land?","answer":17,"explain":"12 and 5 more is 17."},{"kind":"numeric","prompt":"A bee is on 20. It flies 4 steps backward. Where does it land?","answer":16,"explain":"20 take away 4 is 16."},{"kind":"numeric","prompt":"A squirrel starts on 10. It jumps 2 back, 5 forward, then 3 back. Where does it land?","answer":10,"explain":"10 to 8, then 13, then 10."},{"kind":"numeric","prompt":"A frog starts on 15. It jumps 2 forward, 7 back, then 3 back. Where does it land?","answer":7,"explain":"15 to 17, then 10, then 7."}]},{"id":"fn3","title":"Skip Counting Forward","icon":"🐸","kind":"lesson","story":"Jumpy the frog hops in big steps. Can you spot his pattern?","teach":[{"title":"Jump in twos, fives and tens","body":"In twos: 2, 4, 6, 8, 10. In fives: 5, 10, 15, 20. In tens: 10, 20, 30.","visual":"🐸"},{"title":"Find the pattern","body":"The jump size stays the same every time. 1, 4, 7 grows by 3.","visual":"🔢"}],"questions":[{"kind":"numeric","prompt":"Fill the blank: 40, 45, 50, ___","answer":55,"explain":"Each jump is 5, so 50 and 5 more is 55."},{"kind":"numeric","prompt":"Fill the blank: 1, 4, 7, ___","answer":10,"explain":"Each jump is 3, so 7 and 3 more is 10."},{"kind":"mcq","prompt":"Start at 4 and count in twos. Which number will you land on?","options":["9","18","13","17"],"answer":1,"explain":"4, 6, 8, 10, 12, 14, 16, 18. Only even numbers appear."},{"kind":"mcq","prompt":"Start at 10 and count in tens. Which number will you land on?","options":["95","77","100","45"],"answer":2,"explain":"10, 20, 30 ... all the way to 100."}]},{"id":"fn4","title":"Jumping Backward","icon":"⏪","kind":"lesson","story":"The frog must hop back across the pond! Count backward to stay dry.","teach":[{"title":"Count backward","body":"Going back means the numbers get smaller. 10, 9, 8, 7.","visual":"⏪"},{"title":"Backward skips","body":"Back in fives: 70, 65, 60. Back in tens: 100, 90, 80.","visual":"🐸"}],"questions":[{"kind":"numeric","prompt":"Fill the blank: 40, 37, 34, ___","answer":31,"explain":"Each jump back is 3, so 34 minus 3 is 31."},{"kind":"numeric","prompt":"Fill the blank: 70, 65, 60, ___","answer":55,"explain":"Each jump back is 5, so 60 minus 5 is 55."},{"kind":"numeric","prompt":"Viraaj counts backward in twos from 20. How many steps to reach 0?","answer":10,"explain":"20, 18, 16, 14, 12, 10, 8, 6, 4, 2, 0 is 10 steps."},{"kind":"mcq","prompt":"Chavi counts in twos from 10. Will she say 43?","options":["Yes, she will say 43","Yes, before 45","Yes, after 41","No, 43 is not in her count"],"answer":3,"explain":"From 10 in twos she says only even numbers, and 43 is odd."}]},{"id":"fn5","title":"The Number Chart Window","icon":"🪟","kind":"lesson","story":"Lakshanya has a number window. Slide it over the chart to find hidden numbers!","teach":[{"title":"Left, right, up, down","body":"Right is 1 more. Left is 1 less. Down is 10 more. Up is 10 less.","visual":"🪟"},{"title":"Just before","body":"The number just before 10 is 9. Just before 20 is 19.","visual":"📋"}],"questions":[{"kind":"numeric","prompt":"The window is on 28. Which number is on top of it?","answer":18,"explain":"Up is 10 less, so 28 minus 10 is 18."},{"kind":"mcq","prompt":"The window is on 28. Which number is below it?","options":["29","38","27","18"],"answer":1,"explain":"Down is 10 more, so 28 plus 10 is 38."},{"kind":"numeric","prompt":"What is 10 more than 53?","answer":63,"explain":"53 and 10 more is 63."},{"kind":"numeric","prompt":"Which number comes just before 40?","answer":39,"explain":"39 comes right before 40."}]},{"id":"fn6","title":"Guess and Play","icon":"🎲","kind":"lesson","story":"It is game time at the mela! Guess the secret number and roll the dice.","teach":[{"title":"Guess my number","body":"Ask yes or no questions. Is it more than 50? Is it less than 20?","visual":"🤔"},{"title":"Dice and patterns","body":"Add the dots on two dice. Block patterns grow by a bigger step each time.","visual":"🎲"}],"questions":[{"kind":"mcq","prompt":"My secret number is 30. Does it have zero as a digit?","options":["Yes","Only sometimes","No"],"answer":0,"explain":"30 has a 3 and a 0, so yes."},{"kind":"numeric","prompt":"Two dice show 4 and 5. What is the sum?","answer":9,"explain":"4 plus 5 is 9."},{"kind":"mcq","prompt":"What is the smallest sum you can get with two dice?","options":["12","1","2","0"],"answer":2,"explain":"Each die shows at least 1, so 1 plus 1 is 2."},{"kind":"numeric","prompt":"Blocks grow 1, 3, 6, ___. Add 2, then 3, then 4. What is next?","answer":10,"explain":"The next jump is 4, and 6 plus 4 is 10."}]},{"id":"fn-boss","title":"Boss: The Counting Crab","icon":"🦀","kind":"boss","boss":{"name":"Counting Crab","taunt":"Snip snap! Can you count up to 100?"},"story":"A giant crab guards the mela gate! Use all your number skills to win.","teach":[{"title":"Number power","body":"Use tens and ones, skip counting, and the number chart.","visual":"🧮"}],"questions":[{"kind":"numeric","prompt":"A ginladi has 4 rows of 10 beads and 7 more beads. How many beads?","answer":47,"explain":"4 tens is 40, and 7 more makes 47."},{"kind":"numeric","prompt":"A frog starts on 30. It jumps 2 forward, then 5 backward. Where does it land?","answer":27,"explain":"30 to 32, then 27."},{"kind":"numeric","prompt":"Fill the blank: 60, 70, 80, ___","answer":90,"explain":"Each jump is 10, so 80 and 10 more is 90."},{"kind":"numeric","prompt":"Fill the blank: 100, 90, 80, ___","answer":70,"explain":"Each jump back is 10, so 80 minus 10 is 70."},{"kind":"mcq","prompt":"The number window is on 74. Which number is on top of it?","options":["75","73","64","84"],"answer":2,"explain":"Up is 10 less, so 74 minus 10 is 64."},{"kind":"numeric","prompt":"Two dice show 5 and 6. What is the sum?","answer":11,"explain":"5 plus 6 is 11."},{"kind":"mcq","prompt":"Start at 4 and count in twos. Will you say 17?","options":["Yes, after 15","Yes","No, only even numbers"],"answer":2,"explain":"4, 6, 8 ... are all even, so 17 is never said."}]}]},{"id":"shadowstory2","index":3,"name":"Shadow Story","subtitle":"2D shapes","emoji":"🎭","palette":{"from":"#f472b6","to":"#831843"},"lessons":[{"id":"ss1","title":"Shadow Play","icon":"🔦","kind":"lesson","story":"Nakul sees a shadow play at the village fair. Let us find out how shadows form!","teach":[{"title":"Light makes shadows","body":"A shadow forms when something blocks the light. No light means no shadow.","visual":"🔦"},{"title":"Big and small shadows","body":"A torch close to a toy makes a big shadow. A torch far away makes a small one.","visual":"🧸"}],"questions":[{"kind":"mcq","prompt":"What do we need to see a shadow? 🌞","options":["Light","Water","Silence","Darkness"],"answer":0,"explain":"A shadow forms when an object blocks light."},{"kind":"mcq","prompt":"Nakul turns off all the lights in a dark room. What happens to his shadow? 🌑","options":["It vanishes","It turns red","It gets bigger","It stays the same"],"answer":0,"explain":"With no light, there is no shadow."},{"kind":"mcq","prompt":"Nakul moves the torch closer to a toy 🧸. The shadow becomes...","options":["Green","Gone","Smaller","Bigger"],"answer":3,"explain":"A torch near the toy makes a big shadow."},{"kind":"mcq","prompt":"When is your shadow the shortest? The sun is high up in the sky. ☀️","options":["Early morning","Late evening","At night","At noon"],"answer":3,"explain":"At noon the sun is high, so shadows are short."}]},{"id":"ss2","title":"Trace and Hide","icon":"✏️","kind":"lesson","story":"Circle, Rectangle, Triangle and Square are playing hide and seek. Can you find them?","teach":[{"title":"Trace it!","body":"Put an object on paper and draw around it. You get its flat shape.","visual":"✏️"},{"title":"Shape friends hide","body":"Circle and rectangle hide in clocks and photo frames. Triangle and square hide in pizza slices and tiles.","visual":"🔺"}],"questions":[{"kind":"mcq","prompt":"Lina traces a bottle cap. Which shape does she get?","options":["Circle","Square","Rectangle","Triangle"],"answer":0,"explain":"A bottle cap is round, so its trace is a circle."},{"kind":"mcq","prompt":"Rani traces an eraser 🧽 on paper. Which shape does she get?","options":["Square","Circle","Rectangle","Triangle"],"answer":2,"explain":"An eraser has four sides, two long and two short."},{"kind":"mcq","prompt":"Triangle wants to hide. Which is a good place?","options":["A coin 🪙","A pizza slice 🍕","A ball ⚽","A clock 🕒"],"answer":1,"explain":"A pizza slice has three corners, like a triangle."},{"kind":"mcq","prompt":"Rectangle wants to hide. Which is a good place?","options":["A photo frame 🖼️","A coin 🪙","A clock 🕒","A ball ⚽"],"answer":0,"explain":"A photo frame is a rectangle. The others are round."}]},{"id":"ss3","title":"Sides and Corners","icon":"📐","kind":"lesson","story":"Triangle and Square are confused. Let us count their sides and corners!","teach":[{"title":"Triangle","body":"A triangle has 3 sides and 3 corners.","visual":"🔺"},{"title":"Square and rectangle","body":"A square and a rectangle each have 4 sides and 4 corners. A circle has no corners.","visual":"🟦"}],"questions":[{"kind":"numeric","prompt":"How many corners does a triangle have? 🔺","answer":3,"explain":"A triangle has 3 corners."},{"kind":"numeric","prompt":"How many sides does a square have? 🟦","answer":4,"explain":"A square has 4 sides."},{"kind":"mcq","prompt":"Which shape has no corners?","options":["Square","Circle","Rectangle","Triangle"],"answer":1,"explain":"A circle is round. It has no corners."},{"kind":"numeric","prompt":"A triangle 🔺 and a square 🟦 stand together. How many corners in all?","answer":7,"explain":"3 corners and 4 corners make 7 corners."}]},{"id":"ss4","title":"Catch the Corner","icon":"🏃","kind":"lesson","story":"Naveen and friends play Catch the Corner. Stand at a corner or you are out!","teach":[{"title":"Straight edges","body":"A table top has straight edges and corners. Run to a corner and stay safe!","visual":"🪑"},{"title":"Curved edges","body":"A round table has a curved edge and no corners. Balls and coins are curved too.","visual":"⚽"}],"questions":[{"kind":"mcq","prompt":"Can the corner game be played at a round table? 🔴","options":["Yes, it has 3 corners","Yes, it has 4 corners","No, it has no corners","Yes, it has 2 corners"],"answer":2,"explain":"A round table has a curved edge and no corners."},{"kind":"mcq","prompt":"Which has straight edges?","options":["A round plate 🍽️","A book 📕","A coin 🪙","A ball ⚽"],"answer":1,"explain":"A book has straight edges and 4 corners."},{"kind":"mcq","prompt":"Which has a curved edge?","options":["A TV 📺","A clock 🕒","A door 🚪","A photo frame 🖼️"],"answer":1,"explain":"A clock is round, so its edge is curved."},{"kind":"numeric","prompt":"6 children play. Only 4 can stand at the 4 corners of the table. How many are out?","answer":2,"explain":"6 take away 4 is 2 children out."}]},{"id":"ss5","title":"Origami Fun","icon":"📄","kind":"lesson","story":"Time to fold paper! Make a paper dog from a square sheet.","teach":[{"title":"Fold a square","body":"A square paper has 4 corners and 4 edges. Fold it corner to corner to get a triangle.","visual":"📄"},{"title":"Fold again","body":"A triangle has 3 corners. Fold a square side to side to get a rectangle.","visual":"🐶"}],"questions":[{"kind":"numeric","prompt":"How many corners does a square paper have? 📄","answer":4,"explain":"A square has 4 corners."},{"kind":"mcq","prompt":"You fold a square paper corner to corner. Which shape do you get?","options":["Star","Circle","Triangle","Square"],"answer":2,"explain":"Joining two opposite corners gives a triangle."},{"kind":"numeric","prompt":"How many corners does your triangle fold have? 🔺","answer":3,"explain":"A triangle has 3 corners."},{"kind":"mcq","prompt":"You fold a square paper side to side. Which shape do you get?","options":["Circle","Rectangle","Triangle","Hexagon"],"answer":1,"explain":"Folding side to side gives a shape with 4 sides, a rectangle."}]},{"id":"ss6","title":"Patterns","icon":"🎨","kind":"lesson","story":"Radha makes a mehandi pattern. Kikku the rabbit hops on tiles in a pattern too!","teach":[{"title":"Shape patterns","body":"A pattern repeats again and again. Look at what comes next.","visual":"🔺"},{"title":"Number patterns","body":"Some patterns add the same number each time. 5, 10, 15 adds 5 each time.","visual":"🐰"}],"questions":[{"kind":"mcq","prompt":"What comes next? 🔺⭕🔺⭕🔺","options":["⭕","⬛","🔺","🟦"],"answer":0,"explain":"The pattern is triangle, circle, triangle, circle. Circle comes next."},{"kind":"numeric","prompt":"Extend the pattern: 5, 10, 15, __","answer":20,"explain":"Each time we add 5. 15 and 5 make 20."},{"kind":"numeric","prompt":"Kikku hops on tiles 1, 4, 7, 10. Which tile is next?","answer":13,"explain":"He jumps 3 each time. 10 and 3 make 13."},{"kind":"numeric","prompt":"Extend the pattern: 1, 6, 11, __","answer":16,"explain":"Each time we add 5. 11 and 5 make 16."}]},{"id":"ss-boss","title":"Shadow Showdown","icon":"🎭","kind":"boss","boss":{"name":"Shadow Puppet King","taunt":"My shadows hide shapes. Can you find them all?"},"story":"The Shadow Puppet King hides all the shapes. Use what you learnt to win!","teach":[{"title":"Shape review","body":"Triangle: 3 corners. Square and rectangle: 4 corners. Circle: none.","visual":"🎭"}],"questions":[{"kind":"mcq","prompt":"What do we need to make a shadow? 🔦","options":["Water","Sand","Dark","Light"],"answer":3,"explain":"Shadows form when something blocks light."},{"kind":"mcq","prompt":"Rani traces a coin 🪙. Which shape does she get?","options":["Square","Rectangle","Circle","Triangle"],"answer":2,"explain":"A coin is round, so the trace is a circle."},{"kind":"numeric","prompt":"How many corners does a triangle have? 🔺","answer":3,"explain":"A triangle has 3 corners."},{"kind":"numeric","prompt":"A triangle 🔺 and a square 🟦 together. How many sides in all?","answer":7,"explain":"3 sides and 4 sides make 7 sides."},{"kind":"mcq","prompt":"Which shape has 3 sides?","options":["Circle","Square","Rectangle","Triangle"],"answer":3,"explain":"A triangle has 3 sides and 3 corners."},{"kind":"mcq","prompt":"Which table has no corners? 🪑","options":["A round table","A rectangle table","A square table"],"answer":0,"explain":"A round table has a curved edge and no corners."},{"kind":"numeric","prompt":"Extend the pattern: 5, 10, 15, 20, __","answer":25,"explain":"Each time we add 5. 20 and 5 make 25."}]}]},{"id":"playlines2","index":4,"name":"Playing with Lines","subtitle":"Lines","emoji":"📐","palette":{"from":"#34d399","to":"#065f46"},"lessons":[{"id":"pl1","title":"Standing Lines","icon":"🧍","kind":"lesson","story":"Lina and Rani join a yoga class. The teacher says, \"Stand tall like a tree!\"","teach":[{"title":"Standing line","body":"A standing line goes straight up and down. It is also called a vertical line.","visual":"🧍"},{"title":"Look around you","body":"A flagpole, a door edge and a tall candle all have standing lines.","visual":"🚩"}],"questions":[{"kind":"mcq","prompt":"Which has a standing line? 🚩 flagpole or 🛏️ bed top?","options":["🛏️ bed top","🚩 flagpole","🌈 rainbow","🛝 slide"],"answer":1,"explain":"A flagpole goes straight up and down, so it is a standing line."},{"kind":"mcq","prompt":"A standing line is also called a ___ line.","options":["vertical","horizontal","round","curved"],"answer":0,"explain":"Standing line and vertical line mean the same thing."},{"kind":"numeric","prompt":"Count the standing lines: | | | | |","answer":5,"explain":"There are 5 lines like |, so the answer is 5."},{"kind":"mcq","prompt":"In yoga, Lina stands tall with her back straight. Which line is she like?","options":["a slanting line","a curved line","a standing line","a sleeping line"],"answer":2,"explain":"Standing straight up and down makes a standing line."}]},{"id":"pl2","title":"Sleeping Lines","icon":"😴","kind":"lesson","story":"Rani lies flat on her yoga mat. \"I am a sleeping line now!\" she laughs.","teach":[{"title":"Sleeping line","body":"A sleeping line lies flat from side to side. It is also called a horizontal line.","visual":"😴"},{"title":"Where do we see it?","body":"A table top, a yoga mat and a train track lying flat are sleeping lines.","visual":"🛤️"}],"questions":[{"kind":"mcq","prompt":"Which has a sleeping line? 🧘 mat lying flat or 🗼 tall tower?","options":["🗼 tall tower","🌲 tall tree","🧘 mat lying flat","🚩 flagpole"],"answer":2,"explain":"A mat lying flat goes from side to side, so it is a sleeping line."},{"kind":"mcq","prompt":"A sleeping line is also called a ___ line.","options":["horizontal","curved","slanting","vertical"],"answer":0,"explain":"Sleeping line and horizontal line mean the same thing."},{"kind":"numeric","prompt":"Count the sleeping lines: — — — — —","answer":5,"explain":"There are 5 lines like —, so the answer is 5."},{"kind":"mcq","prompt":"Rani lies flat on the floor. Which line is she like?","options":["a slanting line","a standing line","a curved line","a sleeping line"],"answer":3,"explain":"Lying flat from side to side makes a sleeping line."}]},{"id":"pl3","title":"Slanting Lines","icon":"🪜","kind":"lesson","story":"At the park, Lina climbs a ladder leaning on a wall. It is not up-down or flat!","teach":[{"title":"Slanting line","body":"A slanting line is tilted. It is not standing and not sleeping.","visual":"🪜"},{"title":"Slanting things","body":"A slide, a leaning ladder and a roof are slanting lines.","visual":"🛝"}],"questions":[{"kind":"mcq","prompt":"Which is a slanting line? 🛝 slide or 🚩 flagpole?","options":["📏 ruler lying flat","🚩 flagpole","⚽ ball","🛝 slide"],"answer":3,"explain":"A slide is tilted, so it is a slanting line."},{"kind":"numeric","prompt":"Count the slanting lines: / / / / / /","answer":6,"explain":"There are 6 lines like /, so the answer is 6."},{"kind":"mcq","prompt":"A ladder leans on the wall. What kind of line is it?","options":["curved line","standing line","sleeping line","slanting line"],"answer":3,"explain":"A leaning ladder is tilted, so it is slanting."},{"kind":"mcq","prompt":"The letter A has two slanting lines and one more line. Which one?","options":["another slanting line","a sleeping line","a standing line","a curved line"],"answer":1,"explain":"The middle bar of A lies flat, so it is a sleeping line."}]},{"id":"pl4","title":"Straight or Curved?","icon":"🧵","kind":"lesson","story":"Rani holds a thread. Pull it tight, and it is straight. Let it loose, and it bends!","teach":[{"title":"Straight lines","body":"Pull a thread tight. It makes a straight line. Standing, sleeping and slanting lines are all straight.","visual":"🧵"},{"title":"Curved lines","body":"Bring your hands closer. The loose thread bends into a curved line. A rainbow is curved.","visual":"🌈"}],"questions":[{"kind":"mcq","prompt":"Which line is curved? 🌈 rainbow or 📏 ruler edge?","options":["📏 ruler edge","🪜 ladder","🚩 flagpole","🌈 rainbow"],"answer":3,"explain":"A rainbow bends, so it has a curved line."},{"kind":"mcq","prompt":"A tight thread makes what kind of line?","options":["a straight line","a round line","a curved line","a wavy line"],"answer":0,"explain":"A tight thread does not bend, so it is straight."},{"kind":"mcq","prompt":"Which is NOT a straight line?","options":["a sleeping line","a standing line","a curved line","a slanting line"],"answer":2,"explain":"Standing, sleeping and slanting lines are straight. Curved lines bend."},{"kind":"numeric","prompt":"Count the curved shapes: ☁️ 🌈 📏 🌙 🚩","answer":3,"explain":"The cloud, rainbow and moon are curved. That makes 3."}]},{"id":"pl5","title":"Lines in Yoga and Letters","icon":"🧘","kind":"lesson","story":"Lina and Rani try yoga poses. They spot lines in every pose, and in letters too!","teach":[{"title":"Lines in yoga","body":"Stand straight and your body is a standing line. Slant your arms and they make slanting lines.","visual":"🧘"},{"title":"Lines in letters","body":"H has two standing lines and one sleeping line. Z has two sleeping lines and one slanting line.","visual":"🔤"}],"questions":[{"kind":"mcq","prompt":"Rani curves her back in a pose. What line does her back make?","options":["a sleeping line","a curved line","a standing line","a straight line"],"answer":1,"explain":"A bent back makes a curved line."},{"kind":"numeric","prompt":"The letter H has 2 standing lines and 1 sleeping line. How many lines in all?","answer":3,"explain":"2 + 1 = 3 lines."},{"kind":"mcq","prompt":"Which letter has only curved lines? 🔤 O, L, T or H?","options":["H","T","O","L"],"answer":2,"explain":"O is round and bends all the way, so it is curved."},{"kind":"mcq","prompt":"The letter L has one standing line and one more. Which one?","options":["a slanting line","another standing line","a curved line","a sleeping line"],"answer":3,"explain":"The bottom of L lies flat, so it is a sleeping line."}]},{"id":"pl6","title":"Fun with Folding and Art","icon":"🎨","kind":"lesson","story":"Lina folds a paper and sees creases. Rani draws a Warli design with simple lines.","teach":[{"title":"Creases are lines","body":"Fold a paper in half. The crease is a straight line. Fold again to get more creases.","visual":"📄"},{"title":"Art with lines","body":"Artists make Madhubani and Warli art with straight and curved lines. We can make shapes with lines too!","visual":"🎨"}],"questions":[{"kind":"mcq","prompt":"You fold a paper in half. What kind of line is the crease?","options":["a round line","a curved line","a wavy line","a straight line"],"answer":3,"explain":"A fold in paper makes a straight crease."},{"kind":"numeric","prompt":"A paper has 2 creases. You fold it and make 3 more. How many creases now?","answer":5,"explain":"2 + 3 = 5 creases."},{"kind":"mcq","prompt":"A triangle is made with 3 straight lines. How many lines make a triangle?","options":["5","3","2","4"],"answer":1,"explain":"A triangle has 3 straight sides."},{"kind":"mcq","prompt":"Which shape can you draw with only curved lines? 🔵 circle or 🔺 triangle?","options":["🔵 circle","▭ rectangle","🟥 square","🔺 triangle"],"answer":0,"explain":"A circle is made of one curved line."}]},{"id":"pl-boss","title":"Line Master Challenge","icon":"📐","kind":"boss","boss":{"name":"Wobbly the Line Wizard","taunt":"Can you tell my straight lines from my curvy ones?"},"story":"Wobbly the Line Wizard tangles all the lines! Help Lina and Rani sort them out.","teach":[{"title":"Review","body":"Standing lines go up and down. Sleeping lines lie flat. Slanting lines tilt. Curved lines bend.","visual":"📐"}],"questions":[{"kind":"mcq","prompt":"Which line goes straight up and down?","options":["sleeping line","standing line","slanting line","curved line"],"answer":1,"explain":"A standing line, or vertical line, goes up and down."},{"kind":"mcq","prompt":"Which line lies flat from side to side?","options":["curved line","sleeping line","slanting line","standing line"],"answer":1,"explain":"A sleeping line, or horizontal line, lies flat."},{"kind":"mcq","prompt":"A slide is tilted. Which line is it?","options":["curved line","standing line","sleeping line","slanting line"],"answer":3,"explain":"A tilted line is a slanting line."},{"kind":"mcq","prompt":"Which line bends and is not straight?","options":["sleeping line","slanting line","standing line","curved line"],"answer":3,"explain":"Only the curved line bends."},{"kind":"numeric","prompt":"Count the standing lines: | | | | | — — /","answer":5,"explain":"Only the lines like | are standing. There are 5."},{"kind":"numeric","prompt":"A picture has 3 straight lines and 2 curved lines. How many lines in all?","answer":5,"explain":"3 + 2 = 5 lines."},{"kind":"mcq","prompt":"Which has a sleeping line? 🚩 flagpole or 🧘 yoga mat lying flat?","options":["🌈 rainbow","🧘 yoga mat lying flat","🚩 flagpole","🪜 leaning ladder"],"answer":1,"explain":"A mat lying flat is a sleeping line."}]}]},{"id":"decoration2","index":5,"name":"Decoration for Celebration!","subtitle":"Add and subtract","emoji":"🎊","palette":{"from":"#4ade80","to":"#14532d"},"lessons":[{"id":"dc1","title":"Garlands of Ten","icon":"🌼","kind":"lesson","story":"Rohan and his friends are decorating for the festival! Each garland has 10 flowers.","teach":[{"title":"One garland is a ten","body":"One garland has 10 flowers. 3 garlands have 30 flowers.","visual":"🌼"},{"title":"Tens and ones","body":"3 garlands and 7 loose flowers make 30 + 7 = 37 flowers.","visual":"🎊"}],"questions":[{"kind":"numeric","prompt":"Each garland has 10 flowers 🌼. How many flowers in 4 garlands?","answer":40,"explain":"4 tens make 40 flowers."},{"kind":"numeric","prompt":"Rohan has 2 garlands and 5 loose flowers. How many flowers in all?","answer":25,"explain":"20 + 5 = 25 flowers."},{"kind":"mcq","prompt":"Akash has 5 garlands and 3 flowers. How many flowers does he have?","options":["8","35","503","53"],"answer":3,"explain":"5 garlands is 50, and 50 + 3 = 53."},{"kind":"numeric","prompt":"Zoha has 63 flowers. How many full garlands can she make?","answer":6,"explain":"63 is 6 tens and 3 ones, so 6 garlands."}]},{"id":"dc2","title":"Adding Garlands Together","icon":"➕","kind":"lesson","story":"Suwali and Rohan bring their flowers together. How many do they have in all?","teach":[{"title":"Add ones, then tens","body":"For 12 + 53, add ones: 2 + 3 = 5. Add tens: 1 + 5 = 6. Answer 65.","visual":"🌸"},{"title":"Jump on the number line","body":"For 24 + 43, jump 40 to reach 64. Then jump 3 more to reach 67.","visual":"🧮"}],"questions":[{"kind":"numeric","prompt":"Zoha has 43 flowers. Akash brings 20 more. How many flowers now?","answer":63,"explain":"43 + 20 = 63. Only the tens change."},{"kind":"mcq","prompt":"What is 25 + 12?","options":["27","37","47","36"],"answer":1,"explain":"Ones: 5 + 2 = 7. Tens: 2 + 1 = 3. So 37."},{"kind":"numeric","prompt":"Start at 22. Jump 10, then jump 6. Where do you land?","answer":38,"explain":"22 + 10 = 32, then 32 + 6 = 38."},{"kind":"numeric","prompt":"What is 24 + 43?","answer":67,"explain":"24 + 40 = 64, then 64 + 3 = 67."}]},{"id":"dc3","title":"Ten Ones Make a Ten","icon":"🔟","kind":"lesson","story":"Mahi and Isha are playing with blocks. Their ones add up to more than 9!","teach":[{"title":"Carry a ten","body":"For 36 + 47, ones: 6 + 7 = 13. That is 1 ten and 3 ones.","visual":"🧱"},{"title":"Finish the sum","body":"Write 3 in ones. Add the new ten: 3 + 4 + 1 = 8 tens. Answer 83.","visual":"✅"}],"questions":[{"kind":"numeric","prompt":"What is 46 + 39?","answer":85,"explain":"Ones: 6 + 9 = 15. Tens: 4 + 3 + 1 = 8. So 85."},{"kind":"mcq","prompt":"In 36 + 47, we get 6 + 7 = 13 ones. How many ones do we write?","options":["13","3","6","1"],"answer":1,"explain":"13 ones is 1 ten and 3 ones. Write 3 and carry the ten."},{"kind":"numeric","prompt":"Heena has 34 red marbles and 57 blue marbles. How many marbles in all?","answer":91,"explain":"34 + 57 = 91 marbles."},{"kind":"numeric","prompt":"What is 45 + 35?","answer":80,"explain":"5 + 5 = 10 ones is 1 ten. Tens: 4 + 3 + 1 = 8. So 80."}]},{"id":"dc4","title":"Counting the Diyas","icon":"🪔","kind":"lesson","story":"Diya makers sold some of their diyas. Help count how many are left!","teach":[{"title":"Take away","body":"75 diyas, and 35 are sold. 75 − 35 = 40 diyas are left.","visual":"🪔"},{"title":"Jump back","body":"To do 19 − 15, jump back 10 first. Then jump back 5 more to reach 4.","visual":"↩️"}],"questions":[{"kind":"numeric","prompt":"There are 32 diyas 🪔. 12 are sold. How many are left?","answer":20,"explain":"32 − 12 = 20 diyas."},{"kind":"mcq","prompt":"To do 19 − 15, jump back 10 first. Then jump back how many?","options":["5","15","4","10"],"answer":0,"explain":"15 is 10 and 5, so jump back 5 more."},{"kind":"numeric","prompt":"What is 45 − 12?","answer":33,"explain":"Ones: 5 − 2 = 3. Tens: 4 − 1 = 3. So 33."},{"kind":"mcq","prompt":"Ruby has 14 stickers and gives away none. How many are left?","options":["1","14","0","13"],"answer":1,"explain":"Taking away 0 leaves the same number. 14 − 0 = 14."}]},{"id":"dc5","title":"Open a Garland","icon":"🎀","kind":"lesson","story":"Jyoti has 4 garlands and 6 flowers. Mummy wants 18 flowers!","teach":[{"title":"Not enough ones","body":"In 46 − 18, we have 6 ones. We cannot take 8 from 6.","visual":"🤔"},{"title":"Open one garland","body":"Open 1 garland. Now 16 ones. 16 − 8 = 8. Tens: 3 − 1 = 2. Answer 28.","visual":"🌼"}],"questions":[{"kind":"numeric","prompt":"Jyoti has 46 flowers. She gives 18 away. How many flowers are left?","answer":28,"explain":"46 − 18 = 28 flowers."},{"kind":"numeric","prompt":"What is 54 − 28?","answer":26,"explain":"Open a ten: 14 − 8 = 6. Tens: 4 − 2 = 2. So 26."},{"kind":"numeric","prompt":"Jyoti has 73 flowers. She gives 47 to her mother. How many are left?","answer":26,"explain":"13 − 7 = 6 ones. 6 − 4 = 2 tens. So 26."},{"kind":"mcq","prompt":"What is 93 − 48?","options":["55","35","45","54"],"answer":2,"explain":"13 − 8 = 5 ones. 8 − 4 = 4 tens. So 45."}]},{"id":"dc6","title":"Sums and Facts Together","icon":"🎁","kind":"lesson","story":"Hania and Mansi are buying a gift for Mummy. They need to add and subtract!","teach":[{"title":"Find the missing number","body":"To solve 14 + __ = 20, do 20 − 14 = 6. So the missing number is 6.","visual":"❓"},{"title":"Fact family","body":"20, 30 and 50 go together. 20 + 30 = 50 and 50 − 20 = 30.","visual":"👨‍👩‍👧"}],"questions":[{"kind":"numeric","prompt":"Avni skipped 12 times. She needs 20 skips in all. How many more skips?","answer":8,"explain":"20 − 12 = 8 more skips."},{"kind":"numeric","prompt":"20, 30 and 50 are a fact family. 50 − 20 = what?","answer":30,"explain":"50 − 20 = 30, because 20 + 30 = 50."},{"kind":"numeric","prompt":"A wrapper costs ₹24 and ribbons cost ₹37. How much money is spent?","answer":61,"explain":"24 + 37 = 61 rupees."},{"kind":"numeric","prompt":"They had ₹78 and spent ₹61. How much money is left?","answer":17,"explain":"78 − 61 = 17 rupees."}]},{"id":"dc-boss","title":"Festival Decoration Boss","icon":"🎊","kind":"boss","boss":{"name":"Garland Tangler","taunt":"My flowers are all mixed up! Can you sort them?"},"story":"The Garland Tangler has tied up all the flowers! Use adding and taking away to free them.","teach":[{"title":"Review","body":"Add ones, then tens. Carry a ten if ones reach 10. Open a ten if you need more ones.","visual":"🎊"}],"questions":[{"kind":"numeric","prompt":"Rohan has 5 garlands and 6 flowers. How many flowers in all?","answer":56,"explain":"5 tens and 6 ones is 56."},{"kind":"numeric","prompt":"What is 35 + 24?","answer":59,"explain":"Ones: 5 + 4 = 9. Tens: 3 + 2 = 5. So 59."},{"kind":"numeric","prompt":"What is 38 + 27?","answer":65,"explain":"8 + 7 = 15, carry a ten. 3 + 2 + 1 = 6. So 65."},{"kind":"numeric","prompt":"35 + __ = 60. What is the missing number?","answer":25,"explain":"60 − 35 = 25, so 35 + 25 = 60."},{"kind":"mcq","prompt":"What is 52 − 37?","options":["25","15","89","11"],"answer":1,"explain":"Open a ten: 12 − 7 = 5. Tens: 4 − 3 = 1. So 15."},{"kind":"numeric","prompt":"What is 22 − 22?","answer":0,"explain":"Taking away all of a number leaves 0."},{"kind":"numeric","prompt":"Anushka has 63 shells. She gives 26 to her brother. How many are left?","answer":37,"explain":"63 − 26 = 37 shells."}]}]},{"id":"ranigift2","index":6,"name":"Rani's Gift","subtitle":"Measuring length","emoji":"🛏️","palette":{"from":"#a78bfa","to":"#4c1d95"},"lessons":[{"id":"rg1","title":"Handspans","icon":"🖐️","kind":"lesson","story":"Raja Jagdeep wants a carved bed for his queen. It must be 10 handspans long!","teach":[{"title":"Measure with your hand","body":"Open your hand wide. That is a handspan. Count how many handspans fit along a thing.","visual":"🖐️"},{"title":"Count each span","body":"Put one handspan after another. Count 1, 2, 3 and so on. The last number is the length.","visual":"🔢"}],"questions":[{"kind":"mcq","prompt":"Which can you use to measure a table without a ruler?","options":["Colours","Songs","Handspans","Smells"],"answer":2,"explain":"We can lay our hand again and again and count."},{"kind":"numeric","prompt":"The Raja wanted a bed 10 handspans long. The bed is only 8 handspans. How many handspans are missing?","answer":2,"explain":"10 - 8 = 2 handspans are missing."},{"kind":"mcq","prompt":"Rani's bed is 10 handspans. A desk is 4 handspans. Which is longer?","options":["They are the same","Cannot say","The desk","The bed"],"answer":3,"explain":"10 is more than 4, so the bed is longer."},{"kind":"numeric","prompt":"Mina measures her book. It is 3 handspans long. She adds 2 more handspans. How long now?","answer":5,"explain":"3 + 2 = 5 handspans."}]},{"id":"rg2","title":"Same Unit, Same Answer","icon":"🤝","kind":"lesson","story":"The carpenter said 8 handspans. Another man said 14! The Mantri had a clever idea.","teach":[{"title":"Hands are different","body":"A big hand covers more. A small hand covers less. So the counts can be different.","visual":"🖐️"},{"title":"Use the same unit","body":"To get the same answer, everyone must measure with the same thing. Use one hand or one tool.","visual":"📏"}],"questions":[{"kind":"mcq","prompt":"The bed was 8 handspans for the Raja but 14 for a boy. Why?","options":["The bed grew","They counted in sleep","The bed was wet","Their hands are different sizes"],"answer":3,"explain":"A small hand needs more handspans to cover the same bed."},{"kind":"mcq","prompt":"Who will get a BIGGER count for the same desk?","options":["A child with a small hand","A man with a big hand","Both always the same","Nobody"],"answer":0,"explain":"A small hand covers less each time, so you count more."},{"kind":"mcq","prompt":"What did the Mantri want everyone to do?","options":["Use different hands","Measure with the same unit","Guess only","Stop measuring"],"answer":1,"explain":"Using the same unit gives everyone the same answer."},{"kind":"numeric","prompt":"A rope is 6 big clips long. One big clip is the same as 2 small clips. How many small clips long is the rope?","answer":12,"explain":"6 big clips, each 2 small clips. 6 + 6 = 12 small clips."}]},{"id":"rg3","title":"Longer or Shorter?","icon":"🛤️","kind":"lesson","story":"Kavita is late for school! Which path will get her there fastest?","teach":[{"title":"Longest and shortest","body":"The shortest path is the quickest way. The longest path takes more time.","visual":"🛤️"},{"title":"Check with thread","body":"Lay a thread along a path. Then compare thread lengths to find the longest.","visual":"🧵"}],"questions":[{"kind":"mcq","prompt":"Path A is 5 steps, path B is 9 steps, path C is 7 steps. Which is the shortest?","options":["All same","Path A","Path C","Path B"],"answer":1,"explain":"5 is the smallest number, so path A is shortest."},{"kind":"mcq","prompt":"Path A is 5 steps, path B is 9 steps, path C is 7 steps. Which is the longest?","options":["Path C","Path B","All same","Path A"],"answer":1,"explain":"9 is the biggest number, so path B is longest."},{"kind":"numeric","prompt":"Kavita takes the 9 step path. The short path is 5 steps. How many steps does she waste?","answer":4,"explain":"9 - 5 = 4 steps more."},{"kind":"mcq","prompt":"Which is longer: a pencil ✏️ or a school bus 🚌?","options":["The bus","The pencil","Cannot say","Same"],"answer":0,"explain":"A bus is much longer than a pencil."},{"kind":"numeric","prompt":"A thread for path 1 is 7 handspans. The thread for path 2 is 12 handspans. How many more is path 2?","answer":5,"explain":"12 - 7 = 5 handspans more."}]},{"id":"rg4","title":"How Many Blocks Tall?","icon":"🧱","kind":"lesson","story":"Rani stacks blocks next to her toys. Let us find out how tall each toy is!","teach":[{"title":"Stack and count","body":"Stack blocks beside a toy. Count the blocks to find how tall it is.","visual":"🧱"},{"title":"Compare heights","body":"More blocks means taller. Fewer blocks means shorter.","visual":"🦒"}],"questions":[{"kind":"mcq","prompt":"The giraffe 🦒 is 9 blocks tall. The monkey 🐒 is 4 blocks tall. Who is taller?","options":["The giraffe","The monkey","Cannot say","Same"],"answer":0,"explain":"9 blocks is more than 4 blocks."},{"kind":"numeric","prompt":"The giraffe is 9 blocks tall. The monkey is 4 blocks tall. How many blocks taller is the giraffe?","answer":5,"explain":"9 - 4 = 5 blocks."},{"kind":"numeric","prompt":"A toy is 3 blocks tall. A toy dog is 4 blocks tall. If you stack them, how many blocks tall?","answer":7,"explain":"3 + 4 = 7 blocks."},{"kind":"mcq","prompt":"Toys A, B, C are 6, 2 and 8 blocks tall. Which is the shortest?","options":["Toy A","All same","Toy B","Toy C"],"answer":2,"explain":"2 is the smallest number of blocks."},{"kind":"numeric","prompt":"Toys are 6, 2 and 8 blocks tall. How many blocks is the tallest toy?","answer":8,"explain":"8 is the biggest of 6, 2 and 8."}]},{"id":"rg5","title":"Heavy and Light","icon":"⚖️","kind":"lesson","story":"At Pumpkin's Chaupal, the vegetables argue. Who is the heaviest? Let us use a balance!","teach":[{"title":"Use a balance","body":"The heavier side of a balance goes down. The lighter side goes up.","visual":"⚖️"},{"title":"Heavier and lighter","body":"A watermelon is heavier than a carrot. A carrot is lighter than a watermelon.","visual":"🍉"}],"questions":[{"kind":"mcq","prompt":"Which is heavier: a watermelon 🍉 or a carrot 🥕?","options":["The watermelon","Same","The carrot","Cannot say"],"answer":0,"explain":"A watermelon weighs much more than a carrot."},{"kind":"mcq","prompt":"On a balance, one side goes down. That side is...","options":["Empty","Lighter","Heavier","Wet"],"answer":2,"explain":"The heavier side goes down."},{"kind":"mcq","prompt":"Which is lighter: a feather 🪶 or a stone 🪨?","options":["Cannot say","The feather","The stone","Same"],"answer":1,"explain":"A feather weighs very little."},{"kind":"numeric","prompt":"1 coconut weighs the same as 2 mangoes. A watermelon weighs 6 mangoes. How many coconuts balance the watermelon?","answer":3,"explain":"Each coconut is 2 mangoes. 6 mangoes make 3 coconuts."},{"kind":"mcq","prompt":"A pumpkin is heavier than a brinjal. A brinjal is heavier than a carrot. Which is lightest?","options":["The brinjal","All same","The carrot","The pumpkin"],"answer":2,"explain":"Pumpkin is heaviest, then brinjal, so carrot is lightest."}]},{"id":"rg6","title":"Glasses of Water","icon":"🥤","kind":"lesson","story":"Raghu makes nimbu pani for Grandma. He must count glasses and spoons carefully!","teach":[{"title":"Measure with a glass","body":"We can measure water with a glass. Count how many glasses fill a bottle.","visual":"🥤"},{"title":"Make more glasses","body":"For 1 glass: 1 glass water, 1 spoon sugar, 2 spoons lemon juice. For 3 glasses, use 3 times as much.","visual":"🍋"}],"questions":[{"kind":"numeric","prompt":"Raghu's bottle holds 4 glasses of water. His friend's bottle holds 3 glasses. How many more glasses does Raghu's hold?","answer":1,"explain":"4 - 3 = 1 glass more."},{"kind":"numeric","prompt":"For 3 glasses of nimbu pani, Raghu uses 1 spoon of sugar for each glass. How many spoons of sugar?","answer":3,"explain":"1 + 1 + 1 = 3 spoons."},{"kind":"numeric","prompt":"One glass needs 2 spoons of lemon juice. How many spoons for 3 glasses?","answer":6,"explain":"2 + 2 + 2 = 6 spoons."},{"kind":"mcq","prompt":"A bottle holds 4 glasses. A jug holds 6 glasses. Which holds more?","options":["Same","Cannot say","The bottle","The jug"],"answer":3,"explain":"6 glasses is more than 4 glasses."}]},{"id":"rg-boss","title":"The Carved Bed Challenge","icon":"🛏️","kind":"boss","boss":{"name":"King Jagdeep's Bed","taunt":"Can you measure my bed the right way?"},"story":"The carved bed is ready! Show the Raja you can measure length, height and weight.","teach":[{"title":"Measuring review","body":"Use the same unit every time. Count units for length. A balance shows heavier and lighter.","visual":"📏"}],"questions":[{"kind":"mcq","prompt":"Why must everyone use the same unit to measure the bed?","options":["To make it longer","So everyone gets the same answer","To make it heavy","No reason"],"answer":1,"explain":"The same unit gives the same count."},{"kind":"numeric","prompt":"The Raja wants 10 handspans. The bed is 8 handspans. How many more are needed?","answer":2,"explain":"10 - 8 = 2."},{"kind":"mcq","prompt":"A small hand and a big hand measure one desk. Who counts MORE handspans?","options":["Cannot say","The big hand","Same","The small hand"],"answer":3,"explain":"A small hand covers less each time."},{"kind":"numeric","prompt":"The tall giraffe is 9 blocks. The monkey is 4 blocks. How many blocks taller is the giraffe?","answer":5,"explain":"9 - 4 = 5."},{"kind":"mcq","prompt":"Path A is 6 steps. Path B is 10 steps. Which is shorter?","options":["Same","Cannot say","Path B","Path A"],"answer":3,"explain":"6 is less than 10."},{"kind":"mcq","prompt":"Which is heavier: an elephant 🐘 or a mouse 🐭?","options":["The elephant","Same","The mouse","Cannot say"],"answer":0,"explain":"An elephant weighs much more."},{"kind":"numeric","prompt":"1 coconut is the same as 2 mangoes. How many mangoes balance 4 coconuts?","answer":8,"explain":"4 + 4 = 8 mangoes, since 2 mangoes for each coconut."}]}]},{"id":"grouping2","index":7,"name":"Grouping and Sharing","subtitle":"Multiply and share","emoji":"🍬","palette":{"from":"#22d3ee","to":"#164e63"},"lessons":[{"id":"gs1","title":"Adding Equal Groups","icon":"🚗","kind":"lesson","story":"Lina is counting wheels on the road. Each car has the same number of wheels!","teach":[{"title":"Equal groups","body":"Each car has 4 wheels. Every group has the same number.","visual":"🚗"},{"title":"Add again and again","body":"2 + 2 + 2 + 2 = 8. We add 2 four times.","visual":"🚲"}],"questions":[{"kind":"numeric","prompt":"Each auto has 3 wheels. 2 autos. 3 + 3 = ?","answer":6,"explain":"3 + 3 = 6 wheels."},{"kind":"numeric","prompt":"Each bicycle has 2 wheels. 4 bicycles. 2 + 2 + 2 + 2 = ?","answer":8,"explain":"2 + 2 + 2 + 2 = 8 wheels."},{"kind":"mcq","prompt":"Which adds the wheels of 3 autos? Each auto has 3 wheels.","options":["3 + 2","2 + 2 + 2","3 + 3 + 3","3 + 3"],"answer":2,"explain":"3 autos means we add 3 three times."},{"kind":"numeric","prompt":"A car has 4 wheels. 3 cars. 4 + 4 + 4 = ?","answer":12,"explain":"4 + 4 + 4 = 12 wheels."}]},{"id":"gs2","title":"Times and the × Sign","icon":"✖️","kind":"lesson","story":"Ramya shows Lina a quick trick. Count groups instead of adding again and again!","teach":[{"title":"Times","body":"2 groups of 3 is 6. We say 2 times 3 is 6.","visual":"🛺"},{"title":"The × sign","body":"We write times as ×. So 4 × 2 = 8.","visual":"✖️"}],"questions":[{"kind":"numeric","prompt":"3 + 3 + 3 + 3 = 12. 4 times 3 is ?","answer":12,"explain":"4 groups of 3 make 12."},{"kind":"mcq","prompt":"Which way writes 5 groups of 2?","options":["5 × 2","5 × 5","5 + 2","2 − 5"],"answer":0,"explain":"Groups of means times, so 5 × 2."},{"kind":"numeric","prompt":"7 cars, 4 wheels each. 7 times 4 is ?","answer":28,"explain":"7 fours are 28 wheels."},{"kind":"numeric","prompt":"3 butterflies. Each has 2 wings. 3 × 2 = ?","answer":6,"explain":"2 + 2 + 2 = 6 wings."}]},{"id":"gs3","title":"Tables of 2, 3, 5 and 10","icon":"📋","kind":"lesson","story":"Lina finds a table of numbers on a mela board. Let us fill it in!","teach":[{"title":"Table of 2","body":"2 ones are 2. 2 twos are 4. 2 threes are 6.","visual":"✌️"},{"title":"Table of 5 and 10","body":"5 × 1 = 5, 5 × 2 = 10, 5 × 3 = 15. 10 × 1 = 10.","visual":"🖐️"}],"questions":[{"kind":"numeric","prompt":"2 × 3 = ?","answer":6,"explain":"2 threes are 6."},{"kind":"numeric","prompt":"3 × 3 = ?","answer":9,"explain":"3 threes are 9."},{"kind":"numeric","prompt":"5 × 3 = ?","answer":15,"explain":"5 threes are 15."},{"kind":"numeric","prompt":"5 × 2 = ?","answer":10,"explain":"5 twos are 10."}]},{"id":"gs4","title":"Flowers and Bindis","icon":"💐","kind":"lesson","story":"Gopal and Ram are making flower bouquets for the mela. Let us count their flowers!","teach":[{"title":"Swap the numbers","body":"3 groups of 4 is 12. 4 groups of 3 is also 12.","visual":"💐"},{"title":"Solve a story","body":"8 packets, 5 bindis each. We write 8 × 5 = 40.","visual":"🔴"}],"questions":[{"kind":"numeric","prompt":"Gopal makes 3 bouquets. Each has 4 flowers. 3 × 4 = ?","answer":12,"explain":"3 groups of 4 make 12 flowers."},{"kind":"numeric","prompt":"Ram makes 4 bouquets. Each has 3 flowers. 4 × 3 = ?","answer":12,"explain":"4 groups of 3 also make 12."},{"kind":"mcq","prompt":"Which gives the same answer as 5 × 4?","options":["4 × 5","4 × 4","5 × 5","5 + 4"],"answer":0,"explain":"Swapping the numbers gives the same total."},{"kind":"numeric","prompt":"Rita buys 6 pencils. Each costs ₹4. 6 × 4 = ? rupees","answer":24,"explain":"6 fours are 24, so she pays ₹24."}]},{"id":"gs5","title":"Let Us Share","icon":"🍬","kind":"lesson","story":"Two hungry brothers find gulab jamuns! They share them equally, one by one.","teach":[{"title":"Share equally","body":"Give 1 to you, 1 to me. Keep going. Both get the same!","visual":"🤝"},{"title":"Count each share","body":"8 sweets shared by 2 is 4 each. 4 for you, 4 for me.","visual":"🍬"}],"questions":[{"kind":"numeric","prompt":"Share 8 gulab jamuns equally between 2 brothers. How many each?","answer":4,"explain":"4 for you and 4 for me makes 8."},{"kind":"numeric","prompt":"Share 6 laddoos equally on 3 plates. How many on each plate?","answer":2,"explain":"2 laddoos on each plate. 2 + 2 + 2 = 6."},{"kind":"mcq","prompt":"Is it equal sharing? You get 5 sweets. I get 2 sweets.","options":["Yes","Only on Sunday","No"],"answer":2,"explain":"5 and 2 are not the same, so it is not equal."},{"kind":"numeric","prompt":"Ritu draws 12 bindis equally on 2 cones. How many on each cone?","answer":6,"explain":"6 + 6 = 12, so 6 on each cone."}]},{"id":"gs6","title":"How Many Groups?","icon":"📿","kind":"lesson","story":"Garima has 20 star beads. She puts 5 beads on each bracelet. How many bracelets?","teach":[{"title":"Make groups","body":"20 beads, 5 in each bracelet. Make groups of 5 until the beads are gone.","visual":"📿"},{"title":"Count the groups","body":"5, 10, 15, 20. We made 4 groups. So 4 bracelets.","visual":"⭐"}],"questions":[{"kind":"numeric","prompt":"Garima has 20 beads. 5 beads make 1 bracelet. How many bracelets?","answer":4,"explain":"4 groups of 5 make 20."},{"kind":"numeric","prompt":"25 roses. 5 roses go in each vase. How many vases?","answer":5,"explain":"5 vases hold 25 roses, since 5 fives are 25."},{"kind":"numeric","prompt":"A tailor has 30 buttons. 6 buttons go on each shirt. How many shirts?","answer":5,"explain":"5 shirts, because 5 times 6 is 30."},{"kind":"numeric","prompt":"Share 24 bananas equally among 3 monkeys. How many each?","answer":8,"explain":"8 each, because 3 groups of 8 make 24."}]},{"id":"gs-boss","title":"Sweet Shop Boss","icon":"🍬","kind":"boss","boss":{"name":"Captain Gulab Jamun","taunt":"Can you share my sweets and count the groups?"},"story":"Captain Gulab Jamun guards the sweet shop! Use groups, times and sharing to win.","teach":[{"title":"Review","body":"Times means equal groups. Sharing makes equal groups too!","visual":"🍬"}],"questions":[{"kind":"numeric","prompt":"5 + 5 + 5 + 5 = ?","answer":20,"explain":"4 fives are 20."},{"kind":"numeric","prompt":"10 × 1 = ?","answer":10,"explain":"10 ones are 10."},{"kind":"numeric","prompt":"There are 2 plates. Each plate has 3 laddoos. 2 × 3 = ?","answer":6,"explain":"2 threes are 6."},{"kind":"mcq","prompt":"Which is the same as 3 × 5?","options":["3 × 3","5 × 3","5 + 5","3 + 5"],"answer":1,"explain":"Swapping 3 and 5 gives the same answer, 15."},{"kind":"numeric","prompt":"Share 10 sweets equally between 2 friends. How many each?","answer":5,"explain":"5 each, since 5 + 5 = 10."},{"kind":"numeric","prompt":"12 flowers. 4 flowers go in each bouquet. How many bouquets?","answer":3,"explain":"3 bouquets, since 3 groups of 4 make 12."},{"kind":"numeric","prompt":"A bus has 5 seats in each row. 8 rows. 8 × 5 = ?","answer":40,"explain":"8 fives are 40 seats."}]}]},{"id":"season2","index":8,"name":"Which Season is it?","subtitle":"Time","emoji":"🌦️","palette":{"from":"#facc15","to":"#713f12"},"lessons":[{"id":"sn1","title":"Five Seasons","icon":"🌦️","kind":"lesson","story":"Rani opens a magic weather book. Each page shows a different season! Can you name them?","teach":[{"title":"Five seasons in a year","body":"A year has five seasons. They are summer, rainy, autumn, winter and spring.","visual":"🌦️"},{"title":"What each season brings","body":"Summer is hot and sunny. Rainy days bring peacocks and hopping frogs. Autumn leaves fall. Winter is cold. Spring has flowers.","visual":"🌸"}],"questions":[{"kind":"numeric","prompt":"How many seasons are there in one year?","answer":5,"explain":"A year has five seasons."},{"kind":"mcq","prompt":"Peacocks dance and frogs hop in the rain. Which season is it? 🦚🐸","options":["Rainy season","Summer","Winter","Autumn"],"answer":0,"explain":"Rain, peacocks and frogs belong to the rainy season."},{"kind":"mcq","prompt":"Leaves fall on the ground and winds are pleasant. Which season? 🍂","options":["Autumn","Spring","Rainy season","Summer"],"answer":0,"explain":"Falling leaves and pleasant winds mean autumn."},{"kind":"mcq","prompt":"Snow covers everything and we wear sweaters. Which season? ⛄","options":["Spring","Rainy season","Winter","Summer"],"answer":2,"explain":"Snow and sweaters belong to winter."}]},{"id":"sn2","title":"Days of the Week","icon":"📅","kind":"lesson","story":"Lina is planning a week of fun. She must put the seven days in the right order!","teach":[{"title":"Seven days","body":"A week has 7 days. They are Sunday, Monday, Tuesday, Wednesday, Thursday, Friday and Saturday.","visual":"📆"},{"title":"Before and after","body":"After Saturday, a new week starts with Sunday. Yesterday comes before today. Tomorrow comes after today.","visual":"➡️"}],"questions":[{"kind":"numeric","prompt":"How many days are there in a week?","answer":7,"explain":"A week has 7 days."},{"kind":"mcq","prompt":"Which day comes after Tuesday?","options":["Wednesday","Monday","Thursday","Friday"],"answer":0,"explain":"The order is Monday, Tuesday, Wednesday."},{"kind":"mcq","prompt":"Which day comes before Friday?","options":["Wednesday","Thursday","Sunday","Saturday"],"answer":1,"explain":"Thursday comes just before Friday."},{"kind":"mcq","prompt":"Today is Wednesday. Which day is the day after tomorrow?","options":["Thursday","Tuesday","Saturday","Friday"],"answer":3,"explain":"Tomorrow is Thursday. The day after that is Friday."}]},{"id":"sn3","title":"Months of the Year","icon":"🗓️","kind":"lesson","story":"Rani finds a big wall calendar in the mela. It has twelve pages, one for each month!","teach":[{"title":"Twelve months","body":"A year has 12 months. It starts with January and ends with December.","visual":"🗓️"},{"title":"Days in a month","body":"Some months have 31 days. Some have 30 days. February has only 28 days.","visual":"🔢"}],"questions":[{"kind":"numeric","prompt":"How many months are there in a year?","answer":12,"explain":"A year has 12 months."},{"kind":"mcq","prompt":"Which is the first month of the year?","options":["June","January","December","March"],"answer":1,"explain":"The year starts with January."},{"kind":"mcq","prompt":"Which month has only 28 days?","options":["February","October","July","April"],"answer":0,"explain":"February is the shortest month with 28 days."},{"kind":"mcq","prompt":"Which month has 30 days?","options":["May","April","March","July"],"answer":1,"explain":"April, June, September and November have 30 days."}]},{"id":"sn4","title":"Calendar Fun","icon":"📖","kind":"lesson","story":"Lina wants to find her birthday on the calendar. Let us read it together!","teach":[{"title":"Reading a calendar","body":"A calendar shows days and dates. Each row is one week: S M T W T F S.","visual":"📅"},{"title":"Why a calendar?","body":"We use a calendar to know the date, the day and the month. It helps us plan holidays and birthdays.","visual":"🎂"}],"questions":[{"kind":"mcq","prompt":"Look at one row of a calendar:\nS M T W T F S\n1 2 3 4 5 6 7\nWhich day is the 3rd?","options":["Wednesday","Monday","Tuesday","Sunday"],"answer":2,"explain":"S is Sunday on 1, M is Monday on 2, and T is Tuesday on 3."},{"kind":"numeric","prompt":"A month has 30 days. Its Sundays are on 3, 10, 17 and 24. How many Sundays are there?","answer":4,"explain":"Count the dates: 3, 10, 17, 24. That makes 4 Sundays."},{"kind":"numeric","prompt":"Another month has Sundays on 2, 9, 16, 23 and 30. How many Sundays?","answer":5,"explain":"Count the dates: 2, 9, 16, 23, 30. That makes 5 Sundays."},{"kind":"numeric","prompt":"March has 31 days. April has 30 days. How many days in both?","answer":61,"explain":"31 + 30 = 61 days."}]},{"id":"sn5","title":"How Long Does It Take?","icon":"⏳","kind":"lesson","story":"Rani and her family go on a trip to see a big fort. How long will each thing take?","teach":[{"title":"Hours, days and months","body":"Quick jobs take hours, like cooking or playing. Longer jobs take days. Very long things take months.","visual":"⏳"},{"title":"A trip takes time","body":"A trip can last many days. A day trip can last many hours. A train ride can take hours too.","visual":"🚂"}],"questions":[{"kind":"mcq","prompt":"Which takes the longest time? 🌱","options":["Playing with friends","Filling a bucket with water","Cooking rice","A seed growing into a plant"],"answer":3,"explain":"A seed takes months to become a plant."},{"kind":"mcq","prompt":"Which is longer: 1 hour or 1 day?","options":["1 day","They are the same","1 hour"],"answer":0,"explain":"A day has many hours in it."},{"kind":"mcq","prompt":"Cooking dal takes a few... ? 🍲","options":["Years","Hours","Months"],"answer":1,"explain":"Cooking is a quick job. It takes hours."},{"kind":"numeric","prompt":"Rani goes to the park at 2 o'clock. She plays for 3 hours. She leaves at ___ o'clock.","answer":5,"explain":"2 + 3 = 5, so she leaves at 5 o'clock."}]},{"id":"sn6","title":"Reading the Clock","icon":"🕒","kind":"lesson","story":"Gargi is busy all day. She wakes up, goes to school and plays. Help her read the clock!","teach":[{"title":"Two hands","body":"The short hand is the hour hand. The long hand is the minute hand.","visual":"🕐"},{"title":"O'clock and half past","body":"When the long hand is on 12, it is an o'clock time. When the long hand is on 6, it is half past.","visual":"🕧"}],"questions":[{"kind":"mcq","prompt":"Which hand is the long hand on a clock?","options":["The minute hand","The short hand","The hour hand"],"answer":0,"explain":"The long hand is the minute hand."},{"kind":"numeric","prompt":"The long hand points to 12. The short hand points to 7. It is ___ o'clock.","answer":7,"explain":"The short hand tells the hour. It is 7 o'clock."},{"kind":"numeric","prompt":"Gargi wakes up at 6 o'clock. She goes to school 2 hours later. At what o'clock does she go?","answer":8,"explain":"6 + 2 = 8, so she goes at 8 o'clock."},{"kind":"mcq","prompt":"The long hand points to 6. The short hand is just after 3. What time is it?","options":["3 o'clock","Half past 6","6 o'clock","Half past 3"],"answer":3,"explain":"The long hand on 6 means half past. The hour is 3."}]},{"id":"sn-boss","title":"The Time Keeper","icon":"⏰","kind":"boss","boss":{"name":"Captain Tick-Tock","taunt":"Tick-tock! Do you know your seasons, days and clocks?"},"story":"Captain Tick-Tock has mixed up all the seasons and the calendar! Fix time to win.","teach":[{"title":"Time review","body":"A year has 5 seasons and 12 months. A week has 7 days. A clock has an hour hand and a minute hand.","visual":"⏰"}],"questions":[{"kind":"mcq","prompt":"Flowers bloom and birds sing. Which season is it? 🌸🐦","options":["Autumn","Winter","Spring","Summer"],"answer":2,"explain":"Flowers and singing birds mean spring."},{"kind":"mcq","prompt":"Which day comes after Saturday?","options":["Thursday","Friday","Monday","Sunday"],"answer":3,"explain":"A new week starts with Sunday after Saturday."},{"kind":"numeric","prompt":"How many months are there in one year?","answer":12,"explain":"A year has 12 months."},{"kind":"mcq","prompt":"Which month has 28 days?","options":["January","February","August","June"],"answer":1,"explain":"February has 28 days."},{"kind":"numeric","prompt":"A month has Sundays on 1, 8, 15, 22 and 29. How many Sundays?","answer":5,"explain":"Count them: 1, 8, 15, 22, 29. That makes 5."},{"kind":"numeric","prompt":"The long hand is on 12 and the short hand is on 4. It is ___ o'clock.","answer":4,"explain":"The short hand points to the hour, so it is 4 o'clock."},{"kind":"numeric","prompt":"Lina starts a trip at 9 o'clock. She comes back 8 hours later. At what o'clock?","answer":5,"explain":"9 + 8 = 17. On the clock that is 5 o'clock."}]}]},{"id":"funfair2","index":9,"name":"Fun at the Fair","subtitle":"Money","emoji":"🎡","palette":{"from":"#fb7185","to":"#881337"},"lessons":[{"id":"ff1","title":"Coins and Notes","icon":"🪙","kind":"lesson","story":"Rupal reaches the fair with ₹50 in her bag. Let us look at her coins and notes!","teach":[{"title":"Rupees","body":"We pay with coins and notes. Coins are ₹1, ₹2, ₹5 and ₹10.","visual":"🪙"},{"title":"Big notes","body":"Notes are ₹10, ₹20, ₹50, ₹100, ₹200 and ₹500. Add them to find the total.","visual":"💵"}],"questions":[{"kind":"mcq","prompt":"Which note is worth the most money?","options":["₹20 note","₹500 note","₹50 note","₹100 note"],"answer":1,"explain":"₹500 is bigger than ₹100, ₹50 and ₹20."},{"kind":"numeric","prompt":"Rupal has a ₹5 coin, a ₹2 coin and a ₹1 coin. How many rupees in all?","answer":8,"explain":"5 + 2 + 1 = 8 rupees."},{"kind":"numeric","prompt":"Rupal has a ₹10 note and a ₹20 note. How many rupees in all?","answer":30,"explain":"10 + 20 = 30 rupees."},{"kind":"mcq","prompt":"Which one is a coin?","options":["₹5","₹200","₹100","₹500"],"answer":0,"explain":"₹5 is a coin. The others are notes."}]},{"id":"ff2","title":"Paise Coins","icon":"🔍","kind":"lesson","story":"Tejal's grandmother shows her old coins. They are called paise!","teach":[{"title":"Paise and rupees","body":"100 paise make 1 rupee. Two 50 paise coins make ₹1.","visual":"🪙"},{"title":"More old coins","body":"Four 25 paise coins make ₹1. Five 20 paise coins make ₹1.","visual":"👵"}],"questions":[{"kind":"numeric","prompt":"100 paise make how many rupees?","answer":1,"explain":"100 paise = ₹1."},{"kind":"mcq","prompt":"Grandma pays with two 50 paise coins. How much is that?","options":["₹1","₹10","₹50","₹2"],"answer":0,"explain":"50 paise + 50 paise = 100 paise = ₹1."},{"kind":"numeric","prompt":"How many 25 paise coins make ₹1?","answer":4,"explain":"25 + 25 + 25 + 25 = 100 paise, which is ₹1."},{"kind":"numeric","prompt":"How many 20 paise coins make ₹1?","answer":5,"explain":"Five coins of 20 paise make 100 paise, which is ₹1."}]},{"id":"ff3","title":"Ride Tickets","icon":"🎟️","kind":"lesson","story":"Rupal runs to the rides! Each ride needs tickets. How much money will she need?","teach":[{"title":"Many tickets","body":"Each ticket costs the same. Add the price again and again.","visual":"🎟️"},{"title":"Example","body":"2 tickets of ₹10 cost 10 + 10 = ₹20.","visual":"🎡"}],"questions":[{"kind":"numeric","prompt":"A Ferris wheel ticket costs ₹10. Rupal takes 2 tickets. How many rupees?","answer":20,"explain":"10 + 10 = 20 rupees."},{"kind":"numeric","prompt":"A toy train ticket costs ₹15. Rupal takes 2 tickets. How many rupees?","answer":30,"explain":"15 + 15 = 30 rupees."},{"kind":"numeric","prompt":"A swing ticket costs ₹5. How much do 3 tickets cost?","answer":15,"explain":"5 + 5 + 5 = 15 rupees."},{"kind":"mcq","prompt":"Which costs more?","options":["They cost the same","1 ticket of ₹15","2 tickets of ₹10"],"answer":2,"explain":"2 tickets of ₹10 cost ₹20, and that is more than ₹15."}]},{"id":"ff4","title":"How Much Was Spent?","icon":"🧮","kind":"lesson","story":"Rupal's friend has only ₹8 left from ₹50. How much did she spend?","teach":[{"title":"Count up","body":"Start at ₹8. Add on until you reach ₹50. 8 + 20 = 28, 28 + 20 = 48, 48 + 2 = 50.","visual":"➕"},{"title":"Take away","body":"Money spent = money given - money left. 50 - 8 = ₹42.","visual":"➖"}],"questions":[{"kind":"numeric","prompt":"Start with ₹8. Add ₹20 for rides. How many rupees now?","answer":28,"explain":"8 + 20 = 28."},{"kind":"numeric","prompt":"From ₹48, how many more rupees reach ₹50?","answer":2,"explain":"48 + 2 = 50."},{"kind":"numeric","prompt":"Dad gave you ₹40. You have ₹3 left. How many rupees did you spend?","answer":37,"explain":"40 - 3 = 37 rupees spent."},{"kind":"numeric","prompt":"Ria had ₹50. She spent ₹20 on rides and ₹20 on snacks. How much is left?","answer":10,"explain":"20 + 20 = 40 spent. 50 - 40 = 10 left."}]},{"id":"ff5","title":"Pop the Balloon","icon":"🎈","kind":"lesson","story":"Matru finds a balloon game. 3 chances cost ₹10. Let us see what he wins!","teach":[{"title":"Add the prizes","body":"Each balloon hides some money. Add the prizes to find the total won.","visual":"🎈"},{"title":"Make tens","body":"Add numbers that make a ten first. 3 + 17 = 20.","visual":"💰"}],"questions":[{"kind":"numeric","prompt":"Red balloon wins ₹3. Blue wins ₹17. Matru pops both. How much does he win?","answer":20,"explain":"3 + 17 = 20 rupees."},{"kind":"numeric","prompt":"Matru pops balloons with ₹3, ₹17 and ₹22. How much does he win in all?","answer":42,"explain":"3 + 17 = 20, and 20 + 22 = 42 rupees."},{"kind":"mcq","prompt":"Red wins ₹3, blue ₹17, green ₹22, yellow ₹31. Which wins the most?","options":["Blue","Green","Yellow","Red"],"answer":2,"explain":"₹31 is the biggest prize, so yellow wins the most."},{"kind":"numeric","prompt":"Matru pops the yellow ₹31 and the green ₹22. How much does he win?","answer":53,"explain":"31 + 22 = 53 rupees."}]},{"id":"ff6","title":"Let Us Buy!","icon":"🛍️","kind":"lesson","story":"Rupal wants to buy toys and snacks. Does she have enough money?","teach":[{"title":"Enough money?","body":"Money needed = price - money you have. Money left = money you have - price.","visual":"🛍️"},{"title":"Ways to pay","body":"One amount can be paid in many ways. ₹30 is 20 + 10 or 10 + 10 + 10.","visual":"💵"}],"questions":[{"kind":"mcq","prompt":"Which pays exactly ₹30?","options":["₹20 note and ₹10 note","One ₹50 note","₹10 note and ₹10 note","₹20 note and ₹5 coin"],"answer":0,"explain":"20 + 10 = 30 rupees."},{"kind":"numeric","prompt":"A toy costs ₹28. Rupal has ₹20. How many more rupees does she need?","answer":8,"explain":"28 - 20 = 8 more rupees."},{"kind":"numeric","prompt":"Jayant buys pens for ₹25 and a book for ₹30. How much does he spend?","answer":55,"explain":"25 + 30 = 55 rupees."},{"kind":"numeric","prompt":"Meera has ₹50. She buys candy for ₹15. How much is left?","answer":35,"explain":"50 - 15 = 35 rupees left."}]},{"id":"ff-boss","title":"The Fair Gate Guard","icon":"🎡","kind":"boss","boss":{"name":"Captain Coin","taunt":"Can you count every rupee at my fair?"},"story":"Captain Coin guards the fair gate. Answer his money riddles to enter!","teach":[{"title":"Money review","body":"Add to find totals. Take away to find money left. 100 paise = ₹1.","visual":"🎡"}],"questions":[{"kind":"numeric","prompt":"Rupal has a ₹10 note, a ₹20 note and a ₹50 note. How many rupees in all?","answer":80,"explain":"10 + 20 + 50 = 80 rupees."},{"kind":"mcq","prompt":"100 paise are equal to how much?","options":["₹100","₹1","₹10","₹5"],"answer":1,"explain":"100 paise = ₹1."},{"kind":"numeric","prompt":"A boat ticket costs ₹10. How much do 3 tickets cost?","answer":30,"explain":"10 + 10 + 10 = 30 rupees."},{"kind":"numeric","prompt":"Rupal had ₹50. She has ₹9 left. How much did she spend?","answer":41,"explain":"50 - 9 = 41 rupees spent."},{"kind":"numeric","prompt":"Matru pops balloons worth ₹17 and ₹22. How much does he win?","answer":39,"explain":"17 + 22 = 39 rupees."},{"kind":"mcq","prompt":"A kite costs ₹45. Rani has ₹50. What is true?","options":["She has ₹45 left","She has enough, with ₹5 left","She needs ₹5 more","She does not have enough"],"answer":1,"explain":"50 - 45 = 5, so she has enough and ₹5 is left."},{"kind":"numeric","prompt":"Rani has ₹35. Her uncle gives her ₹20 more. How much does she have now?","answer":55,"explain":"35 + 20 = 55 rupees."}]}]},{"id":"datahandling2","index":10,"name":"Data Handling","subtitle":"Tables and charts","emoji":"📊","palette":{"from":"#c084fc","to":"#581c87"},"lessons":[{"id":"dh1","title":"Favourite Colours","icon":"🎨","kind":"lesson","story":"Rani asks her friends, \"Which colour do you like best?\" Help her count the answers!","teach":[{"title":"Data is information","body":"When we ask many friends a question, the answers are called data. We can write data in a table.","visual":"📋"},{"title":"Count and write","body":"Count each colour one by one. Write the number in the table.","visual":"🔢"}],"questions":[{"kind":"numeric","prompt":"Rani's friends chose blue like this: 🔵🔵🔵🔵🔵. How many like blue?","answer":5,"explain":"Count the blue dots: there are 5."},{"kind":"numeric","prompt":"Red: 🔴🔴🔴  Green: 🟢🟢. How many children like red?","answer":3,"explain":"There are 3 red dots."},{"kind":"mcq","prompt":"Red 🔴🔴🔴 | Green 🟢🟢 | Blue 🔵🔵🔵🔵🔵 | Yellow 🟡🟡🟡🟡. Which colour is liked the most?","options":["Red","Green","Blue","Yellow"],"answer":2,"explain":"Blue has 5 dots, the most."},{"kind":"numeric","prompt":"Red 🔴🔴🔴, Green 🟢🟢, Blue 🔵🔵🔵🔵🔵, Yellow 🟡🟡🟡🟡. How many children in all?","answer":14,"explain":"3 + 2 + 5 + 4 = 14 children."}]},{"id":"dh2","title":"Picnic Day","icon":"🧺","kind":"lesson","story":"Lina is at a fruit party! Every child is eating a favourite fruit. Let us count them.","teach":[{"title":"Most liked","body":"The longest row in a table is the most liked. It has the biggest number.","visual":"👑"},{"title":"Least liked","body":"The shortest row is the least liked. It has the smallest number.","visual":"🔍"}],"questions":[{"kind":"mcq","prompt":"Apple 🍎🍎🍎🍎 | Banana 🍌🍌🍌 | Orange 🍊🍊🍊🍊🍊🍊 | Kiwi 🥝🥝 | Guava 🍐🍐🍐🍐🍐. Which fruit is liked the most?","options":["Banana","Apple","Kiwi","Orange"],"answer":3,"explain":"Orange has 6, the biggest number."},{"kind":"mcq","prompt":"Apple 🍎🍎🍎🍎 | Banana 🍌🍌🍌 | Orange 🍊🍊🍊🍊🍊🍊 | Kiwi 🥝🥝 | Guava 🍐🍐🍐🍐🍐. Which fruit is liked the least?","options":["Kiwi","Orange","Apple","Guava"],"answer":0,"explain":"Kiwi has 2, the smallest number."},{"kind":"numeric","prompt":"Banana 🍌🍌🍌. How many children like banana?","answer":3,"explain":"Count the bananas: 3."},{"kind":"numeric","prompt":"Apple 4, Banana 3, Orange 6, Kiwi 2, Guava 5. How many children are at the party?","answer":20,"explain":"4 + 3 + 6 + 2 + 5 = 20 children."}]},{"id":"dh3","title":"More, Less or Equal?","icon":"⚖️","kind":"lesson","story":"Rani and Lina compare their fruit table. Who has more? Who has less?","teach":[{"title":"Compare two rows","body":"The bigger number means more. The smaller number means less.","visual":"↔️"},{"title":"Same number","body":"If both numbers are the same, they are equal.","visual":"🟰"}],"questions":[{"kind":"mcq","prompt":"Guava 🍐🍐🍐🍐🍐 (5) and Apple 🍎🍎🍎🍎 (4). Guava is liked ___ apple.","options":["more than","less than","equal to"],"answer":0,"explain":"5 is bigger than 4, so guava is more."},{"kind":"mcq","prompt":"Apple 🍎🍎🍎🍎 (4) and Banana 🍌🍌🍌 (3). Apple is liked ___ banana.","options":["more than","less than","equal to"],"answer":0,"explain":"4 is bigger than 3."},{"kind":"mcq","prompt":"Kiwi 🥝🥝 (2) and Orange 🍊🍊🍊🍊🍊🍊 (6). Kiwi is liked ___ orange.","options":["equal to","less than","more than"],"answer":1,"explain":"2 is smaller than 6."},{"kind":"mcq","prompt":"Red 🔴🔴🔴🔴 (4) and Yellow 🟡🟡🟡🟡 (4). Red is liked ___ yellow.","options":["less than","equal to","more than"],"answer":1,"explain":"Both are 4, so they are equal."}]},{"id":"dh4","title":"How We Come to School","icon":"🚌","kind":"lesson","story":"Children come to school in many ways. Rani draws a smiley for each child.","teach":[{"title":"A chart of faces","body":"In this chart, one 😀 means 1 student. Count the faces in each row.","visual":"😀"},{"title":"Read the chart","body":"A long row has more students. A short row has fewer students.","visual":"📊"}],"questions":[{"kind":"mcq","prompt":"On foot 😀😀😀😀😀 | Autorickshaw 😀😀 | Bus 😀😀😀😀😀😀 | Bike 😀😀😀 | Bicycle 😀😀😀😀. Most children come by ___.","options":["Bike","Autorickshaw","Bus","On foot"],"answer":2,"explain":"Bus has 6 faces, the most."},{"kind":"mcq","prompt":"On foot 😀😀😀😀😀 | Autorickshaw 😀😀 | Bus 😀😀😀😀😀😀 | Bike 😀😀😀 | Bicycle 😀😀😀😀. Fewest children come by ___.","options":["Bicycle","Bus","Autorickshaw","On foot"],"answer":2,"explain":"Autorickshaw has 2 faces, the least."},{"kind":"numeric","prompt":"Bike 😀😀😀. One 😀 is 1 student. How many students come by bike?","answer":3,"explain":"Count 3 faces, so 3 students."},{"kind":"mcq","prompt":"Bike 😀😀😀 (3) and Bicycle 😀😀😀😀 (4). Bike students are ___ bicycle students.","options":["equal to","more than","less than"],"answer":2,"explain":"3 is smaller than 4."}]},{"id":"dh5","title":"Games We Play","icon":"🏏","kind":"lesson","story":"At the mela ground, children play many games. Let us find how many more play each game.","teach":[{"title":"How many more?","body":"To find how many more, take away the smaller number from the bigger number.","visual":"➖"},{"title":"Use the table","body":"Look at both rows. Count each one. Then find the difference.","visual":"👀"}],"questions":[{"kind":"mcq","prompt":"Gilli-danda 3 | Kabaddi 5 | Pithu 2 | Football 6 | Cricket 7. Which game is liked the most?","options":["Football","Kabaddi","Cricket","Pithu"],"answer":2,"explain":"Cricket has 7, the biggest number."},{"kind":"mcq","prompt":"Gilli-danda 3 | Kabaddi 5 | Pithu 2 | Football 6 | Cricket 7. Which game is liked the least?","options":["Kabaddi","Pithu","Football","Gilli-danda"],"answer":1,"explain":"Pithu has 2, the smallest number."},{"kind":"numeric","prompt":"Football 6 and Cricket 7. How many more children play cricket than football?","answer":1,"explain":"7 - 6 = 1 more child plays cricket."},{"kind":"numeric","prompt":"Kabaddi 5 and Pithu 2. How many more children play kabaddi than pithu?","answer":3,"explain":"5 - 2 = 3 more children."}]},{"id":"dh6","title":"Our Families","icon":"👨‍👩‍👧","kind":"lesson","story":"Lina visits nearby families. She asks about grandparents and writes the answers in a table.","teach":[{"title":"Ask and record","body":"First plan your question. Then ask each family and write the answer in a table.","visual":"✏️"},{"title":"Add up the table","body":"Add all the rows to find the total. Add some rows to find a group.","visual":"➕"}],"questions":[{"kind":"numeric","prompt":"Both grandparents: 4 families. Only grandmother: 2. Only grandfather: 1. No grandparents: 3. How many families did Lina visit?","answer":10,"explain":"4 + 2 + 1 + 3 = 10 families."},{"kind":"numeric","prompt":"Only grandmother: 2 families. Only grandfather: 1 family. How many families live with one grandparent?","answer":3,"explain":"2 + 1 = 3 families."},{"kind":"mcq","prompt":"Both grandparents 4 | Only grandmother 2 | Only grandfather 1 | No grandparents 3. Most families live with ___.","options":["both grandparents","only grandfather","no grandparents","only grandmother"],"answer":0,"explain":"4 is the biggest number."},{"kind":"numeric","prompt":"Families with 2 people: 1. With 3: 3. With 4: 6. With 5: 2. How many families have more than 4 people?","answer":2,"explain":"More than 4 means 5 people. That is 2 families."}]},{"id":"dh-boss","title":"The Chart Champion","icon":"🏆","kind":"boss","boss":{"name":"Professor Tally-Twist","taunt":"Can you read my tricky pet chart?"},"story":"Professor Tally-Twist has mixed up the pet chart! Use all you know about tables to fix it.","teach":[{"title":"Reading a chart","body":"Count each row. The biggest is most, the smallest is least. Subtract to find how many more.","visual":"📊"}],"questions":[{"kind":"mcq","prompt":"Dog 🐶🐶🐶🐶🐶🐶 | Cat 🐱🐱🐱🐱 | Rabbit 🐰🐰 | Fish 🐟🐟🐟. Which pet do the children like the most?","options":["Dog","Fish","Rabbit","Cat"],"answer":0,"explain":"Dog has 6, the most."},{"kind":"mcq","prompt":"Dog 🐶🐶🐶🐶🐶🐶 | Cat 🐱🐱🐱🐱 | Rabbit 🐰🐰 | Fish 🐟🐟🐟. Which pet do the children like the least?","options":["Dog","Fish","Rabbit","Cat"],"answer":2,"explain":"Rabbit has 2, the least."},{"kind":"numeric","prompt":"Dog 🐶🐶🐶🐶🐶🐶 | Cat 🐱🐱🐱🐱 | Rabbit 🐰🐰 | Fish 🐟🐟🐟. How many children like cats?","answer":4,"explain":"Count the cats: 4."},{"kind":"numeric","prompt":"Dog 🐶🐶🐶🐶🐶🐶 | Cat 🐱🐱🐱🐱 | Rabbit 🐰🐰 | Fish 🐟🐟🐟. How many more children like dogs than cats?","answer":2,"explain":"6 - 4 = 2 more."},{"kind":"mcq","prompt":"Dog 🐶🐶🐶🐶🐶🐶 | Cat 🐱🐱🐱🐱 | Rabbit 🐰🐰 | Fish 🐟🐟🐟. Fish are liked ___ rabbits.","options":["more than","less than","equal to"],"answer":0,"explain":"3 is bigger than 2."},{"kind":"numeric","prompt":"Dog 🐶🐶🐶🐶🐶🐶 | Cat 🐱🐱🐱🐱 | Rabbit 🐰🐰 | Fish 🐟🐟🐟. How many children are there in all?","answer":15,"explain":"6 + 4 + 2 + 3 = 15 children."},{"kind":"numeric","prompt":"Rani counted 2 rabbit fans and 3 fish fans. How many children like rabbit or fish?","answer":5,"explain":"2 + 3 = 5 children."}]}]}];